function A({to="/",children,className="",...props}:{to?:string;children:React.ReactNode;className?:string;[key:string]:any}) { return <a href={to} className={className} {...props}>{children}</a>; }
function readLocal(key:string,fallback:string|null=null):string|null { return typeof window==="undefined"?fallback:window.localStorage.getItem(key)??fallback; }
function ButtonLink({to,children,light=false}:{to:string;children:React.ReactNode;light?:boolean}) { return <A to={to} className={`btn ${light?"btn-light":"btn-green"}`}>{children}</A>; }
function MonprojetsolidaireWordmark({compact=false}:{compact?:boolean}) { return <span className={`wordmark ${compact?"compact":""}`}><span className="wordmark-mark">M</span><span>Monprojetsolidaire</span></span>; }
function PwaInstallButton() {
  const [installEvent,setInstallEvent]=useState<any>(null),[installed,setInstalled]=useState(false);
  useEffect(()=>{
    setInstalled(window.matchMedia("(display-mode: standalone)").matches || Boolean((navigator as any).standalone));
    const handlePrompt=(event:Event)=>{event.preventDefault();setInstallEvent(event)};
    const handleInstalled=()=>{setInstalled(true);setInstallEvent(null)};
    window.addEventListener("beforeinstallprompt",handlePrompt);
    window.addEventListener("appinstalled",handleInstalled);
    return()=>{window.removeEventListener("beforeinstallprompt",handlePrompt);window.removeEventListener("appinstalled",handleInstalled)};
  },[]);
  if(installed)return null;
  if(!installEvent)return <span className="install-hint">Ajoutez Monprojetsolidaire à votre écran d’accueil depuis le menu du navigateur.</span>;
  return <button className="install-app-button" onClick={async()=>{await installEvent.prompt();await installEvent.userChoice;setInstallEvent(null)}}>Installer Monprojetsolidaire</button>;
}

